export function oklab(rgb){const [r,g,b]=rgb.map(v=>{v=Math.max(0,Math.min(255,v))/255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4});const l=Math.cbrt(.4122214708*r+.5363325363*g+.0514459929*b),m=Math.cbrt(.2119034982*r+.6806995451*g+.1073969566*b),s=Math.cbrt(.0883024619*r+.2817188376*g+.6299787005*b);return [.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s]}
export function convert({pixels,width,height,palette,settings}){const colors=palette.map(b=>settings.method==='rgb'?b.color:oklab(b.color)),work=new Float32Array(width*height*3),air=new Uint8Array(width*height);for(let i=0;i<air.length;i++){const a=pixels[i*4+3]/255;if(settings.transparent==='air'&&a<.5){air[i]=1;continue}const bg=settings.transparent==='black'?0:255,c=[0,1,2].map(k=>pixels[i*4+k]*a+bg*(1-a)),gray=.2126*c[0]+.7152*c[1]+.0722*c[2];for(let k=0;k<3;k++)work[i*3+k]=Math.max(0,Math.min(255,(gray+(c[k]-gray)*settings.saturation-127.5)*settings.contrast+127.5+settings.brightness))}const near=(rgb,allowed)=>{const v=settings.method==='rgb'?rgb:oklab(rgb);let best=Infinity,idx=0;for(const j of allowed){const c=colors[j];let d=(v[0]-c[0])**2+(v[1]-c[1])**2+(v[2]-c[2])**2;if(settings.smooth)d+=(palette[j].textureVariance||0)/65025*.003;if(d<best){best=d;idx=j}}return idx};let allowed=palette.map((_,i)=>i);if(+settings.maxColors&&+settings.maxColors<allowed.length){const counts=new Uint32Array(palette.length);for(let i=0;i<air.length;i++)if(!air[i])counts[near(Array.from(work.subarray(i*3,i*3+3)),allowed)]++;allowed.sort((a,b)=>counts[b]-counts[a]);allowed=allowed.slice(0,+settings.maxColors)}const out=new Int16Array(air.length).fill(-1);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=y*width+x;if(air[i])continue;const rgb=Array.from(work.subarray(i*3,i*3+3)),j=near(rgb,allowed);out[i]=j;if(+settings.dither){const e=rgb.map((v,k)=>(v-palette[j].color[k])*settings.dither);for(const [dx,dy,f]of[[1,0,7/16],[-1,1,3/16],[0,1,5/16],[1,1,1/16]])if(x+dx>=0&&x+dx<width&&y+dy<height){const q=(y+dy)*width+x+dx;if(!air[q])for(let k=0;k<3;k++)work[q*3+k]+=e[k]*f}}}return Array.from(out)}
export function countsFor(cells){const m=new Map();cells.forEach(i=>{if(i>=0)m.set(i,(m.get(i)||0)+1)});return m}
export function blockPosition(i,w,h){return {x:i%w,y:h-1-Math.floor(i/w),z:0}}
export function rowRuns(cells,w,h,row){const start=(h-1-row)*w,r=[];for(let x=0;x<w;x++){const b=cells[start+x],last=r.at(-1);if(last&&last.block===b){last.count++;last.end=x}else r.push({block:b,count:1,start:x,end:x})}return r}
